import re
from typing import List, Dict, Any, Tuple, Optional

# Helpers are assumed to be available
# node_by_title(doc, title) -> node
# node_by_id(doc, node_id) -> node
# children(doc, node) -> list of child nodes
# scope_nodes(doc, scope) -> child nodes of the scope
# table_rows(node) -> list of (row_index, {column:cell}) tuples

def _parse_object_line(line: str) -> Tuple[str, str]:
    """
    Parse a line from the "Objects" list.
    Example: "Object 0: green metal sphere (color=green, material=metal, shape=sphere)"
    Returns (id, description)
    """
    match = re.match(r'^Object (\d+): (.+?) \((.+)\)', line)
    if match:
        obj_id = match.group(1)
        # Full human readable description: type + attributes
        description = f"{match.group(2)} ({match.group(3)})".strip()
        return obj_id, description
    # Fallback: try a simpler format
    match = re.match(r'^Object (\d+): (.+)', line)
    if match:
        return match.group(1), match.group(2).strip()
    raise ValueError(f"Cannot parse object line: {line}")

def _first_state_by_obj(motion_rows: List[Tuple[int, Dict[str, str]]]) -> Dict[str, Tuple[int, Dict[str, str]]]:
    """
    Return mapping from object id to (first_frame, row_dict).
    """
    first_map: Dict[str, Tuple[int, Dict[str, str]]] = {}
    for row_index, cols in motion_rows:
        obj_desc = cols.get('object', '')
        # Object column format: "<id> <description>"
        m = re.match(r'^(\d+)', obj_desc)
        if not m:
            continue
        obj_id = m.group(1)
        frame = int(cols.get('frame', '0'))
        if obj_id not in first_map or frame < first_map[obj_id][0]:
            first_map[obj_id] = (frame, cols)
    return first_map

# Public API
def entities(doc: Dict, scope: str) -> List[Dict[str, Any]]:
    # Find the Objects list node
    obj_node = node_by_title(doc, f"{scope}: Objects")
    if obj_node is None or obj_node.get('kind') != 'list':
        return []
    res: List[Dict[str, Any]] = []
    for line in obj_node.get('lines', []):
        try:
            obj_id, desc = _parse_object_line(line)
            res.append({"id": obj_id, "description": desc})
        except ValueError:
            continue
    return res

def recorded_end(doc: Dict, scope: str) -> Optional[float]:
    mlog_node = node_by_title(doc, f"{scope}: Motion log")
    if mlog_node is None or mlog_node.get('kind') != 'table':
        return None
    max_frame = 0
    for _, cols in table_rows(mlog_node):
        try:
            frm = int(cols.get('frame', '0'))
            if frm > max_frame:
                max_frame = frm
        except ValueError:
            continue
    return float(max_frame) if max_frame else None

def inputs(doc: Dict, scope: str) -> List[Dict[str, Any]]:
    # Build entity lookup
    ents = {e["id"]: e for e in entities(doc, scope)}
    # Motion log
    mlog_node = node_by_title(doc, f"{scope}: Motion log")
    if mlog_node is None:
        return []
    motion_rows = table_rows(mlog_node)
    first_states = _first_state_by_obj(motion_rows)
    inputs_list: List[Dict[str, Any]] = []
    node_id = mlog_node.get('node_id')
    for obj_id, (frm, cols) in first_states.items():
        # Prepare fields
        fields = {}
        for key in ['x', 'y', 'vx', 'vy', 'speed']:
            val = cols.get(key)
            if val is None or val == "":
                continue
            try:
                fields[key] = float(val)
            except ValueError:
                fields[key] = val
        inp = {
            "id": f"in_{obj_id}",
            "time": float(frm),
            "kind": "initial_state",
            "entities": [obj_id],
            "fields": fields,
            "src": [[node_id, _row_index_of_node_row(mlog_node, frm, obj_id)]]
        }
        inputs_list.append(inp)
    return inputs_list

def outcomes(doc: Dict, scope: str) -> List[Dict[str, Any]]:
    ev_node = node_by_title(doc, f"{scope}: Events")
    if ev_node is None:
        return []
    outcomes_list: List[Dict[str, Any]] = []
    for line_index, line in enumerate(ev_node.get('lines', [])):
        # Collision
        m_col = re.match(r'^Frame (\d+): Object (\d+) collides with Object (\d+)', line)
        if m_col:
            frm = float(m_col.group(1))
            obj_a = m_col.group(2)
            obj_b = m_col.group(3)
            outcomes_list.append({
                "time": frm,
                "kind": "collision",
                "entities": [obj_a, obj_b],
                "value": None,
                "src": [[ev_node.get('node_id'), line_index]]
            })
            continue
        # Exit
        m_ex = re.match(r'^Frame (\d+): Object (\d+) exits the scene', line)
        if m_ex:
            frm = float(m_ex.group(1))
            obj_id = m_ex.group(2)
            outcomes_list.append({
                "time": frm,
                "kind": "exit",
                "entities": [obj_id],
                "value": None,
                "src": [[ev_node.get('node_id'), line_index]]
            })
            continue
    return outcomes_list

