def _row_index_of_node_row(node: Dict, frame: int, obj_id: str) -> int:
    """
    Return the index of the row in node['table']['rows'] that matches
    the given frame and object ID. Returns -1 if not found.
    """
    for idx, row in enumerate(node['table']['rows']):
        if row[1].get('frame') == str(frame) and row[1].get('object', '').startswith(obj_id):
            return idx
    return -1

import re
from typing import Any, Dict, List, Tuple, Union, Optional

# --------------------------- helpers ----------------------------
# The following helpers are assumed to be available in the sandbox environment.
# They are widely used in the rest of the implementation.
# def node_by_title(doc: Dict[str, Any], title: str) -> Dict[str, Any]:
#     ...
# def node_by_id(doc: Dict[str, Any], node_id: str) -> Dict[str, Any]:
#     ...
# def children(doc: Dict[str, Any], node: Dict[str, Any]) -> List[Dict[str, Any]]:
#     ...
# def scope_nodes(doc: Dict[str, Any], scope: str) -> List[Dict[str, Any]]:
#     ...
# def table_rows(node: Dict[str, Any]) -> List[Tuple[int, Dict[str, str]]]:
#     ...


# --------------------------- internal utilities ----------------------------
def _parse_obj_line(line: str) -> Tuple[str, str]:
    """Parse an Objects list line.
    Returns tuple (id, description)."""
    m = re.match(r"^Object\s+(\d+):\s+(.+)$", line)
    if not m:
        raise ValueError(f"Could not parse object line: {line}")
    return m.group(1), m.group(2).strip()


def _obj_id_from_object_cell(cell: str) -> Optional[str]:
    """Extract object id from the 'object' cell of the motion log."""
    m = re.match(r"^(\d+)", cell)
    return m.group(1) if m else None


def _ro_num(v: str) -> Union[float, str]:
    """Try to convert a string to a floating point number."""
    try:
        return float(v)
    except Exception:
        return v


def _find_event_line_info(node: Dict[str, Any], line_index: int) -> Tuple[str, float, str, List[str]]:
    """Return (kind, time, entities, cols) for the event line."""
    line = node["lines"][line_index]
    # Collision
    m = re.match(r"^Frame\s+(\d+):\s+Object\s+(\d+)\s+collides\s+with\s+Object\s+(\d+)", line)
    if m:
        return ("collision", float(m.group(1)), [m.group(2), m.group(3)], [])
    # Exit
    m = re.match(r"^Frame\s+(\d+):\s+Object\s+(\d+)\s+exits\s+the\s+scene", line)
    if m:
        return ("exit", float(m.group(1)), [m.group(2)], [])
    # Enter
    m = re.match(r"^Frame\s+(\d+):\s+Object\s+(\d+)\s+enters\s+the\s+scene", line)
    if m:
        return ("enter", float(m.group(1)), [m.group(2)], [])
    # Present
    m = re.match(r"^Frame\s+(\d+):\s+Object\s+(\d+)(?:\s+in\s+view|.*)when\s+the\s+video\s+begins", line)
    if m:
        return ("present", float(m.group(1)), [m.group(2)], [])
    # Unknown / non‑event
    return ("", float("nan"), [], [])


def _object_line_nodes(doc: Dict[str, Any], scope: str) -> Dict[str, Tuple[str, int]]:
    """Return a mapping object_id -> (node_id, line_index) for the Objects list."""
    mapping: Dict[str, Tuple[str, int]] = {}
    node = node_by_title(doc, f"{scope}: Objects")
    if node and node.get("kind") == "list":
        for idx, line in enumerate(node.get("lines", [])):
            try:
                oid, _ = _parse_obj_line(line)
                mapping[oid] = (node["node_id"], idx)
            except Exception:
                continue
    return mapping


def _build_src_for_initial_state(node_id: str, row_index: int, all_columns: List[str]) -> List[Any]:
    """Return a location description for a motion‑log row."""
    return [[node_id, row_index, all_columns]]


# --------------------------- public API ----------------------------
def entities(doc: Dict[str, Any], scope: str) -> List[Dict[str, Any]]:
    """Return list of objects in the given scope."""
    node = node_by_title(doc, f"{scope}: Objects")
    if not node or node.get("kind") != "list":
        return []

    out: List[Dict[str, Any]] = []
    for line in node.get("lines", []):
        try:
            oid, desc = _parse_obj_line(line)
            out.append({"id": oid, "description": desc})
        except Exception:
            continue
    return out


def recorded_end(doc: Dict[str, Any], scope: str) -> Optional[float]:
    """Return the last frame number recorded for the scope."""
    node = node_by_title(doc, f"{scope}: Motion log")
    if not node or node.get("kind") != "table":
        return None

    max_frame = -1
    for _, row in table_rows(node):
        try:
            f = int(row.get("frame", "-1"))
        except Exception:
            continue
        if f > max_frame:
            max_frame = f

    return float(max_frame) if max_frame >= 0 else None


def inputs(doc: Dict[str, Any], scope: str) -> List[Dict[str, Any]]:
    """Return all input records for the given scope."""
    out: List[Dict[str, Any]] = []
    obj_line_map = _object_line_nodes(doc, scope)

    # 1. initial_state from motion log
    mlog = node_by_title(doc, f"{scope}: Motion log")
    if mlog and mlog.get("kind") == "table":
        used_obj: set[str] = set()
        for row_index, row in table_rows(mlog):
            obj_cell = row.get("object", "")
            oid = _obj_id_from_object_cell(obj_cell)
            if not oid or oid in used_obj:
                continue
            used_obj.add(oid)

            # Build fields
            fields: Dict[str, Any] = {}
            for key in ("x", "y", "vx", "vy", "speed"):
                if key in row:
                    fields[key] = _ro_num(row[key]) if row[key] != "" else None

            # Build src: include object description and whole motion‑log row
            src: List[Any] = []
            if oid in obj_line_map:
                src.append(obj_line_map[oid])
            src.append(_build_src_for_initial_state(mlog["node_id"], row_index, ["frame","object","x","y","vx","vy","speed"]))

            out.append({
                "id": f"in_{oid}",
                "time": _ro_num(row.get("frame", "0")),
                "kind": "initial_state",
                "entities": [oid],
                "fields": fields,
                "src": src,
            })

    # 2. present events (objects in view at start)
    ev_node = node_by_title(doc, f"{scope}: Events")
    if ev_node and ev_node.get("kind") == "list":
        for li, line in enumerate(ev_node.get("lines", [])):
            kind, t, ents, _ = _find_event_line_info(ev_node, li)
            if kind != "present":
                continue
            oid = ents[0]
            src: List[Any] = []
            # add object line
            if oid in obj_line_map:
                src.append(obj_line_map[oid])
            # add event line
            src.append([ev_node["node_id"], li])
            out.append({
                "id": f"in_{oid}_present",
                "time": t,
                "kind": "present",
                "entities": [oid],
                "fields": {},
                "src": src,
            })

    # 3. enter events
    if ev_node and ev_node.get("kind") == "list":
        for li, line in enumerate(ev_node.get("lines", [])):
            kind, t, ents, _ = _find_event_line_info(ev_node, li)
            if kind != "enter":
                continue
            oid = ents[0]
            src: List[Any] = []
            if oid in obj_line_map:
                src.append(obj_line_map[oid])
            src.append([ev_node["node_id"], li])
            out.append({
                "id": f"in_{oid}_enter",
                "time": t,
                "kind": "enter",
                "entities": [oid],
                "fields": {},
                "src": src,
            })

    # 4. exit events that are considered inputs (mostly nothing to do)

    return out


def outcomes(doc: Dict[str, Any], scope: str) -> List[Dict[str, Any]]:
    """Return all outcome records for the given scope."""
    out: List[Dict[str, Any]] = []
    ev_node = node_by_title(doc, f"{scope}: Events")
    if not ev_node or ev_node.get("kind") != "list":
        return out

    for li, line in enumerate(ev_node.get("lines", [])):
        kind, t, ents, _ = _find_event_line_info(ev_node, li)
        if kind in ("present", "enter", ""):
            continue  # not a produced event
        if kind == "collision" or kind == "exit":
            out.append({
                "time": t,
                "kind": kind,
                "entities": ents,
                "value": None,
                "src": [[ev_node["node_id"], li]],
            })
    return out


def params(doc: Dict[str, Any], scope: str) -> Dict[str, Any]:
    """Return constants defined in the document for the given scope."""
    # The CLEVRER description listings contain no explicit constants.
    return {}
